def compute(vars):
    shares = vars["v1"]
    average_price = vars["v2"]
    value = shares * average_price
    return {
        "value": value,
        "trace": {
            "shares": shares,
            "average_price_per_share": average_price,
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "currency"
            }
        }
    }
